import{_ as l,a0 as r,w as p,s as a,ao as u,I as i,x as n,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"系统监控中心：一个理想的 Linux 任务管理器和资源监视器 | LCTT x X-CMD","titleTemplate":false,"description":"系统监控中心：一个理想的 Linux 任务管理器和资源监视器 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"系统监控中心：一个理想的 Linux 任务管理器和资源监视器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"系统监控中心：一个理想的 Linux 任务管理器和资源监视器 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211130 System Monitoring Center is an Ideal Task Manager - Resource Monitor for Linux","title":"系统监控中心：一个理想的 Linux 任务管理器和资源监视器","tag":"202112","desc":""},"relativePath":"202112/20211130 System Monitoring Center is an Ideal Task Manager - Resource Monitor for Linux.md","filePath":"[post].md"}'),m={name:"202112/20211130 System Monitoring Center is an Ideal Task Manager - Resource Monitor for Linux.md"};function d(f,t,g,x,C,L){const e=r("Link");return p(),a("div",null,[t[19]||(t[19]=u('<h1 id="系统监控中心-一个理想的-linux-任务管理器和资源监视器" tabindex="-1">系统监控中心：一个理想的 Linux 任务管理器和资源监视器 <a class="header-anchor" href="#系统监控中心-一个理想的-linux-任务管理器和资源监视器" aria-label="Permalink to “系统监控中心：一个理想的 Linux 任务管理器和资源监视器”">​</a></h1><blockquote><p>“系统监控中心”是一个多合一的开源应用，不用使用多种工具就可以监控基本的系统资源情况。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202112/10/131211ng09sz76u2b7gbaw.jpg" alt=""></p><p>在 Linux 上以图形方式监控系统资源可能体验不是很好，这些与你的桌面环境相配套的系统监控工具可能细节有限。</p><p>例如，GNOME 的系统监视器不显示 CPU 频率和温度。</p><p>此外，Linux 的默认系统监控程序通常以简单为目标，而不是提供详细的信息。</p><p>“<ruby>系统监控中心<rt>System Monitoring Center</rt></ruby>” 是一个有用的 GUI 工具，它提供了大量必要的信息。在这篇文章中，让我给你详细介绍一下它。</p><h3 id="系统监控中心-显示基本系统统计信息的-linux-应用" tabindex="-1">系统监控中心：显示基本系统统计信息的 Linux 应用 <a class="header-anchor" href="#系统监控中心-显示基本系统统计信息的-linux-应用" aria-label="Permalink to “系统监控中心：显示基本系统统计信息的 Linux 应用”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center.png?resize=800%2C611&amp;ssl=1" alt=""></p><p>系统监控中心是一个基于 GTK3 和 Python 3 的外观时尚的应用，它为你提供了你想要的所有资源使用数据。</p><p>在我的例子中，我想在使用系统监控工具时关注 CPU 的频率，但 GNOME 的系统监控工具提供不了帮助。所以，这个应用就非常有用了。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center-full-info.png?resize=800%2C585&amp;ssl=1" alt=""></p><p>该应用的用户体验良好，并提供了大量的信息和功能。让我重点介绍一下它的主要功能。</p><blockquote><p>写这篇文章时，该应用程序仍处于测试阶段。因此，你可能会遇到一些错误。然而，我在简短的测试中没有注意到任何问题。</p></blockquote><h3 id="系统监控中心的功能" tabindex="-1">系统监控中心的功能 <a class="header-anchor" href="#系统监控中心的功能" aria-label="Permalink to “系统监控中心的功能”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center-options.png?resize=582%2C576&amp;ssl=1" alt=""></p><p>首先，它可以让你查看 CPU、内存、磁盘、网络、GPU 和传感器的单独统计数据。</p><p>你可以在该工具中看到以下细节信息：</p><ul><li>显示 CPU 状态，包括频率</li><li>能够显示平均使用率或每个核心的使用率</li><li>可以选择 CPU 频率和其他统计的精度</li><li>能够改变图表的颜色</li><li>按用户过滤系统进程并轻松管理它们</li><li>切换一个浮动的摘要小部件，以快速获得信息</li><li>显示磁盘使用信息和连接的驱动器</li><li>在同一个应用中显示详细的系统信息</li><li>控制启动服务和程序</li><li>能够控制状态更新的时间间隔</li><li>应用本身的系统资源使用率较低</li><li>适应系统主题</li></ul><p>虽然它为每个标签（或组件）提供了大量的选项和自定义功能，但我希望它能在未来的更新中包括 RAM 频率等东西。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-cpu-monitoring.png?resize=800%2C599&amp;ssl=1" alt=""></p><p>然而，考虑到它可以同时取代磁盘使用分析器和 <code>neofetch</code> 等终端工具，其余的数据似乎非常有用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/11/system-monitoring-center-process.png?resize=800%2C592&amp;ssl=1" alt=""></p><p>请注意，如果你有多个机箱风扇、独立的排风扇或 AIO，你可能无法得到风扇的数据。温度也可能有或没有，但 CPU 的温度应该是可见的。</p><h3 id="在-linux-中安装系统监控中心" tabindex="-1">在 Linux 中安装系统监控中心 <a class="header-anchor" href="#在-linux-中安装系统监控中心" aria-label="Permalink to “在 Linux 中安装系统监控中心”">​</a></h3><p>你可以使用可用的 deb 包在任何基于 Ubuntu 的发行版上轻松安装它。</p><p>不幸的是，没有可用的其他软件包，只有一个 ZIP 文件，你得手动构建和编译才能安装它。你在 ZIP 文件中可以找到一个脚本来构建 RPM 包。</p>',27)),i("p",null,[t[1]||(t[1]=n("deb 文件可以通过 SourceForge 获得。你点击下面的按钮来下载它，或者在他们的 ",-1)),s(e,{href:"https://kod.pardus.org.tr/Hakan/system-monitoring-center"},{default:o(()=>[...t[0]||(t[0]=[n("GitLab 页面",-1)])]),_:1}),t[2]||(t[2]=n(" 找到。",-1))]),i("ul",null,[i("li",null,[s(e,{href:"https://sourceforge.net/projects/system-monitoring-center/files/latest/download"},{default:o(()=>[...t[3]||(t[3]=[n("下载系统监控中心",-1)])]),_:1})])]),t[20]||(t[20]=i("h3",{id:"总结",tabindex:"-1"},[n("总结 "),i("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t[21]||(t[21]=i("p",null,"系统监控中心是一个开源应用，可以让用户详细了解他们的系统资源，并帮助管理进程。",-1)),t[22]||(t[22]=i("p",null,"对于许多 Linux 用户来说，这是一个非常需要的应用，不需要使用单独的终端/GUI 程序就可以提供详细的信息。",-1)),t[23]||(t[23]=i("hr",null,null,-1)),i("p",null,[t[5]||(t[5]=n("via: ",-1)),s(e,{href:"https://itsfoss.com/system-monitoring-center/"},{default:o(()=>[...t[4]||(t[4]=[n("https://itsfoss.com/system-monitoring-center/",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=n("作者：",-1)),s(e,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...t[6]||(t[6]=[n("Ankush Das",-1)])]),_:1}),t[11]||(t[11]=n(" 选题：",-1)),s(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[7]||(t[7]=[n("lujun9972",-1)])]),_:1}),t[12]||(t[12]=n(" 译者：",-1)),s(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[8]||(t[8]=[n("geekpi",-1)])]),_:1}),t[13]||(t[13]=n(" 校对：",-1)),s(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=n("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[n("Linux中国",-1)])]),_:1}),t[18]||(t[18]=n(" 荣誉推出",-1))])])}const M=l(m,[["render",d]]);export{k as __pageData,M as default};
